<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class UpbringingRatingController extends Controller{
private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head'),403);}
public function merits(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('student_merit_actions as a')->join('students as s','s.id','=','a.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('a.academic_period_id',$p->id)->select('a.*','s.last_name','s.first_name','g.name as group_name')->orderByDesc('a.action_on')->get();$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('s.status','active')->select('s.id','s.last_name','s.first_name','g.name as group_name')->orderBy('s.last_name')->get();return view('upbringing.merits',compact('rows','students'));}
public function meritStore(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['student_id'=>'required|exists:students,id','type'=>'required|in:reward,discipline','action_on'=>'required|date','kind'=>'required|string|max:100','reason'=>'required|string|max:3000','order_number'=>'nullable|string|max:100','order_on'=>'nullable|date','rating_points'=>'required|integer|min:-100|max:100']);DB::table('student_merit_actions')->insert($d+['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Запись добавлена');}
public function meritCancel(Request $r,$id){$this->ok($r);$x=DB::table('student_merit_actions')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);DB::table('student_merit_actions')->where('id',$id)->update(['status'=>'cancelled','updated_at'=>now()]);return back();}
public function ratings(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('student_merit_actions as a',function($j)use($p){$j->on('a.student_id','=','s.id')->where('a.academic_period_id',$p->id)->where('a.status','active');})->where('s.status','active')->groupBy('s.id','s.last_name','s.first_name','g.id','g.name')->select('s.id','s.last_name','s.first_name','g.name as group_name',DB::raw('COALESCE(SUM(a.rating_points),0) rating'))->orderByDesc('rating')->get();$groups=$students->groupBy('group_name')->map(fn($x)=>(object)['name'=>$x->first()->group_name,'students'=>$x->count(),'rating'=>$x->sum('rating')])->sortByDesc('rating')->values();return view('upbringing.ratings',compact('students','groups'));}
public function assignments(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('student_public_assignments as a')->join('students as s','s.id','=','a.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('a.academic_period_id',$p->id)->select('a.*','s.last_name','s.first_name','g.name as group_name')->orderByDesc('a.id')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();return view('upbringing.assignments',compact('rows','students'));}
public function assignmentStore(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['student_id'=>'required|exists:students,id','title'=>'required|string|max:255','starts_on'=>'nullable|date','ends_on'=>'nullable|date']);DB::table('student_public_assignments')->insert($d+['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}